// Independent physical checks on a copy of the saved requested-case prototype.
using System;using System.IO;using System.Linq;using System.Collections.Generic;
using System.Globalization;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro {public static class LatchInProcess {
static JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=64000000};
static Dictionary<string,object> O(object x){return(Dictionary<string,object>)x;}
static double[] N(object x){return((Array)x).Cast<object>().Select(Convert.ToDouble).ToArray();}
static string Hash(string p){using(var f=new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete))using(var h=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
static void Children(IZElement e,List<IZElement> list){var a=e.GetChildrenZArray();for(int i=0;i<e.GetChildrenCount();i++){object x;a.Get(i,out x);list.Add((IZElement)x);}}
static bool At(IZElement e,double[] pos){var m=((IZSceneElement)e).GetTransformToParent();return Enumerable.Range(0,3).All(i=>Math.Abs(m.GetValue(3,i)*1000-pos[i])<.025);}
static void Near(double a,double b,string why){if(Double.IsNaN(a)||Math.Abs(a-b)>.035)throw new Exception(why+" "+a+" != "+b);}
static void Walk(IZElement e,List<IZPart> parts){if(e.Type==eZElementType.Z_ELEMENT_PART){parts.Add((IZPart)e);return;}var a=e.GetChildrenZArray();for(int i=0;i<e.GetChildrenCount();i++){object x;a.Get(i,out x);Walk((IZElement)x,parts);}}
static object Check(Dictionary<string,IZElement> map,object[] specs,object[] cutSpecs){
 var dimensions=new List<object>();foreach(object raw in specs){var p=O(raw);string key=(string)p["key"];var e=map[key];if(!At(e,N(p["initial"])))throw new Exception("Moved incorrectly "+key);
 if(p.ContainsKey("expected_size")){var b=N(((IZPart)e).GetBody(true).GetBoundingBox());var expected=N(p["expected_size"]);for(int i=0;i<3;i++)Near((b[i+3]-b[i])*1000,expected[i],"Size "+key);dimensions.Add(new{key=key,actual_mm=Enumerable.Range(0,3).Select(i=>(b[i+3]-b[i])*1000).ToArray()});}
 else{var bodies=new List<IZPart>();Walk(e,bodies);var points=new List<double[]>();foreach(var b in bodies){var box=N(b.GetBody(true).GetBoundingBox());var m=((IZSceneElement)b).GetTransformToGlobal();for(int mask=0;mask<8;mask++)points.Add(Enumerable.Range(0,3).Select(j=>m.GetValue(3,j)*1000+Enumerable.Range(0,3).Sum(k=>box[k+(((mask>>k)&1)==1?3:0)]*1000*m.GetValue(k,j))).ToArray());}var origin=((IZSceneElement)e).GetTransformToGlobal();var center=Enumerable.Range(0,3).Select(k=>(points.Min(v=>v[k])+points.Max(v=>v[k]))/2).ToArray();for(int k=0;k<3;k++)if(Math.Abs(center[k]-origin.GetValue(3,k)*1000)>160)throw new Exception("Imported geometry detached from mounting anchor "+key);dimensions.Add(new{key=key,bodies=bodies.Count,world_min_mm=Enumerable.Range(0,3).Select(k=>points.Min(v=>v[k])).ToArray(),world_max_mm=Enumerable.Range(0,3).Select(k=>points.Max(v=>v[k])).ToArray()});}}
 var cuts=new List<object>();foreach(object raw in cutSpecs){var c=O(raw);var part=(IZPart)map[(string)c["target"]];var fm=(IZPartFeatureMgr)part;var matches=Enumerable.Range(0,fm.GetFeaturesCount()).Select(fm.GetFeatureAt).Where(f=>((IZElement)f).Name==(string)c["name"]).ToArray();if(matches.Length!=1||matches[0].OperationType!=eZOperationType.Z_SUBTRACT)throw new Exception("Missing/duplicate cut "+c["name"]);var fe=(IZSceneElement)matches[0];var m=fe.GetTransformToParent();var expected=N(c["initial"]);for(int i=0;i<3;i++)Near(m.GetValue(3,i)*1000,expected[i],"Cut anchor "+c["name"]);cuts.Add(new{name=c["name"],feature_id=((IZElement)matches[0]).Id});}
 var pairs=new List<object>();foreach(var kv in map.Where(k=>k.Key.StartsWith("latch/")||k.Key.StartsWith("vent/")||k.Key.StartsWith("handle/"))){string[] bits=kv.Key.Split('/');var targets=bits[0]=="latch"?new[]{"body/"+bits[1],"lid/"+bits[1]}:bits[0]=="vent"?new[]{"body/"+bits[1]}:new[]{"lid/"+bits[1],"roof"};foreach(string target in targets){bool collision=((IZPart)map[target]).HasInterference(kv.Value);pairs.Add(new{hardware=kv.Key,target=target,collision=collision});}}
 return new{dimensions=dimensions,cuts=cuts,interference_pairs=pairs,interference_passed=pairs.All(p=>!(bool)p.GetType().GetProperty("collision").GetValue(p,null)),passed=true};
}
public static int Run(string folder){var report=new Dictionary<string,object>();IZDoc owned=null;IZBaseApp app=null;string input=null;bool pass=false;
 try{var r=O(J.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json"))));if((string)r["contract"]!="rockpro-requested-verify-2027-v1"||System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(r["expected_pid"]))throw new Exception("Wrong request/host");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");input=(string)r["file"];if(Hash(input)!=(string)r["sha256"])throw new Exception("Input changed");string copy=Path.Combine(folder,"verification-copy.ics");File.Copy(input,copy,false);bool already;owned=app.OpenFile2(copy,false,false,out already);if(already){owned=null;throw new Exception("Ownership failure");}var s=(IZSceneDoc)owned;
 var roots=new List<IZElement>();Children(s.GetTopElement(),roots);if(roots.Count!=6)throw new Exception("Expected six groups");var nodes=new List<IZElement>();foreach(var root in roots)Children(root,nodes);if(nodes.Count!=52)throw new Exception("Expected 52 occurrences");var map=new Dictionary<string,IZElement>();
 foreach(object raw in (object[])r["specs"]){var p=O(raw);var hits=nodes.Where(e=>e.Name==(string)p["name"]&&At(e,N(p["initial"]))).ToArray();if(hits.Length!=1)throw new Exception("Ambiguous/misplaced occurrence "+p["key"]);map[(string)p["key"]]=hits[0];}
 report["baseline"]=Check(map,(object[])r["specs"],(object[])r["cuts"]);
 foreach(var kv in O(r["changed_parameters"]))s.ParameterMgr.GetParameterByName(kv.Key).Expression=Convert.ToDouble(kv.Value).ToString("R",CultureInfo.InvariantCulture)+" mm";((IZAssembly)s.GetTopElement()).RegenerateParts(true);s.Update();report["changed"]=Check(map,(object[])r["changed_specs"],(object[])r["changed_cuts"]);
 // The verification copy is disposable; original saved file is never modified.
 if(r.ContainsKey("require_clearance")&&(bool)r["require_clearance"]){foreach(string key in new[]{"baseline","changed"}){var check=report[key];if(!(bool)check.GetType().GetProperty("interference_passed").GetValue(check,null))throw new Exception("Hardware/plywood interference remains: "+key);}}report["node_ids"]=map.ToDictionary(kv=>kv.Key,kv=>kv.Value.Id);owned.Close2(true);owned=null;report["source_unchanged"]=Hash(input)==(string)r["sha256"];if(!(bool)report["source_unchanged"])throw new Exception("Input integrity");pass=true;
 }catch(Exception ex){report["error"]=ex.ToString();}
 finally{if(owned!=null)try{owned.Close2(true);}catch(Exception ex){report["cleanup_error"]=ex.ToString();pass=false;}report["passed"]=pass;File.WriteAllText(Path.Combine(folder,"result.json"),J.Serialize(report));}return pass?0:1;
}
}}
